"""Payment capture flow for the storefront."""
import os

STRIPE_KEY_ENV = "STRIPE_SECRET_KEY"

def capture(order_id, amount_cents):
    key = os.environ.get(STRIPE_KEY_ENV)
    if not key:
        raise RuntimeError("payment key not configured")
    return {"order": order_id, "amount": amount_cents, "status": "captured"}
